export async function retry<T>(
  fn: () => Promise<T>,
  {
    retries = 3,
    delayMs = 100,
    backoffFactor = 2,
  }: { retries?: number; delayMs?: number; backoffFactor?: number } = {},
): Promise<T> {
  let lastError: unknown;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;

      if (attempt === retries) break;

      const delay = delayMs * backoffFactor ** attempt;
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }

  throw lastError;
}

