      } else {
        throw new Error("Circuit breaker is open");
      }
    }

    try {
      const result = await fn();

      if (this.state === "half-open") {
        this.state = "closed";
        this.failures = 0;
      }

      return result;
    } catch (error) {
      this.failures += 1;
      this.lastFailureAt = Date.now();

      if (this.failures >= this.failureThreshold) {
        this.state = "open";
      }

      throw error;
    }
  }
}

